class megazone_client(object):
    """Robot Framework keywords interface"""

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2
    lookup_handler, session_store = aliasing_scope(name=__name__, lookup_arg='session',
                                                   lookup_type=SessionHandler)

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self._session_handler = None

    def wait_for_site_availability(self, url, timeout, interval=1.0):
        """
        Waits until site under given url is reachable or timeout expires
        without creating session.

        :param url: site url
        :param timeout: time to wait for site availability, timeout should be
        greater or equal to 0
        :param interval: time in seconds between checks
        :return: Returns true if site is reachable or False otherwise
        """
        interval = float(interval)
        timeout = float(timeout)
        return SiteHandler.wait_for_site_availability(url, timeout, interval=interval)

    def wait_for_site_unavailability(self, url, timeout, interval=1.0):
        """
        Waits until site under given url is unreachable or timeout expires
        (this is the opposite of wait_for_site_availability())

        :param url: site url
        :param timeout: time to wait for site to go down, timeout should be
         a float greater or equal to 0
        :param interval: time in seconds between checks
        :return: True if site is unreachable, False otherwise
        """
        interval = float(interval)
        timeout = float(timeout)
        return SiteHandler.wait_for_site_unavailability(url, timeout, interval=interval)

    @property
    def session_handler(self):
        if not self._session_handler:
            raise RuntimeError("you need to create session first.")
        return self.session_store.get()

    @session_handler.setter
    def session_handler(self, session):
        self._session_handler = session

    def create_session(self, base_url, user='Nemuadmin', password='nemuuser',
                       port=None, alias=None):
        """
        Creates new session, credentials are the same as in webUI.

        :param base_url: full base url, ex.: "https://10.42.44.200/"
        :param user: username, defaults to "Nemuadmin"
        :param password: password, defaults to "nemuuser"
        :param port: port, defaults to None
        :param alias: (optional) alias that the new session object will be
            identified by. If not specified, string "default" is used.
        """
        self.session_handler = SessionHandler()
        self._session_handler.create_session(base_url=base_url,
                                             username=user,
                                             password=password,
                                             port=port)
        self.session_store.add(self._session_handler, alias)

    @lookup_handler.implicit_lookup
    def teardown_session(self, session=None, timeout=10):
        """Closes connection with webUI.

        Because the server could be unresponsive, the following problems will be ignored:
        * The server did not send any data in the allotted amount of time
        * A proxy error occurred
        * An SSL error occurred

        If any of the above happens, the logout action will be
        retried in 5-seconds intervals until timeout exceeds.

        :param session: (optional) Session to use, can be an alias or
            SessionHandler object.
        :param timeout: (optional) the overall maximum number of seconds
            to wait for logout action
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        session.teardown_session(timeout=timeout)

