    @lookup_handler.implicit_lookup
    def get_vm(self, vm_name=None, session=None, timeout=None):
        """
        Gets values for given VM if provided, otherwise values for all available VMs as dictionary.

        :param vm_name: name of VM, for example: oamVM, cncpVM, uecpVM, ueupVM
        :param session: (optional) Session to use, can be an alias or
            SessionHandler object.
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        :return: values of given vm, if vm_name is None- returns all available
            vms as dictionary.
        """
        logging.warning("This keyword is deprecated. Please use `get_vm_info` instead.")
        timeout = robot_typecasts.time_to_seconds(timeout)
        vm_info = CloudBTS(session).get_vm_statuses(timeout=timeout)
        if vm_name:
            return vm_info[vm_name]

        return vm_info

