    @lookup_handler.implicit_lookup
    def make_snapshot(self, snapshot_path=None, timeout=480, save_location='LOCAL',
                      session=None, **kwargs):
        """
        Makes snapshot and saves it under given path.

        :param snapshot_path: Path where snapshot will be saved if save_location is 'LOCAL'.
        :param save_location: Location where the snapshot will be collected. Possible values: 'LOCAL', 'SBTS', 'SERVER'.
        :param timeout: Time in seconds to wait for snapshot to be ready, defaults to 480.
        :param session: (optional) Session to use, can be an alias or SessionHandler object.
        :param kwargs: To filter snapshot and define what should be collected,
                         specify the collecting details options:

                         * `type` (int or str, defaults to 0): Corresponds to `Type` selector under `Collecting details` section.
                              - 0:	All
                              - 1:	Crash & recovery
                              - 2:	5G User and Control Plane
                              - 3:	5G Control Plane
                              - 4:	HW and SW configuration
                              - 5:	RU only
                         * `level` (int or str, defaults to 0): Corresponds to `Level` selector under `Collecting details` section.
                              - 0:   Full
                              - 1:   Normal
                              - 2:   Minor
                         * `rap` (list of strings or string containing list of strings, defaults to an empty list):
                             equivalent to selecting particular RAPs under `Collect from` section.
                             For example, ['RAP 1', 'RAP 2'] and "['RAP 1', 'RAP 2']" are equivalents to selecting RAP 1 and RAP 2 checkboxes.
                         * `vnf` (str, defaults to 'on'): possible values are 'on' and 'off'.
                             Corresponds to VNF checkbox under `Collect from` section.
                         * `request_id` (str): defaults to '0000'. Corresponds to `Request ID` textbox under `Collecting details` section.

                         When save_location is `SERVER`, then additional parameters are:

                         * `protocol` (str, defaults to 'https')
                         * `username` (str, defaults to an empty string)
                         * `password` (str, defaults to an empty string)
                         * `ipaddr` (str, defaults to an empty string)
                         * `port` (str, defaults to '8080')
                         * `target_path` (str, defaults to '/home/ute')
        """
        save_location = str(save_location)
        timeout = robot_typecasts.time_to_seconds(timeout)
        return ResourceBTS(session).make_snapshot(snapshot_path, timeout, save_location, **kwargs)

