    @lookup_handler.implicit_lookup
    def is_cell_in_state(self, state, number=None, session=None, timeout=None):
        """
        Boolean cell state verification keyword. Possible states: online, offline.

        :param state: parameter that cell should have
        :param number: optional arg pointing at given cell
        :param session: (optional) Session to use, can be an alias or
            SessionHandler object.
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        :return: True if cell (or all cells) are in given state (e.g. online), Fail otherwise
        """
        timeout = robot_typecasts.time_to_seconds(timeout)

        if number:
            return self.get_cell_status(number=int(number), session=session, timeout=timeout) == state
        return all(cell_state == state for cell_state in
                   self.get_cell_status(session=session, timeout=timeout))

