    @lookup_handler.implicit_lookup
    def is_s1_link_in_state(self, state, session=None, timeout=None):
        """
        Boolean S1 link state verification keyword. Possible states: online, offline.

        :param state: state to check for
        :param session: (optional) Session to use, can be an alias or
            SessionHandler object.
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        :return: True if S1 link is in given state, False otherwise
        """
        timeout = robot_typecasts.time_to_seconds(timeout)

        state = state.lower()
        if state not in ['online', 'offline']:
            raise IncorrectParameter('Provided state (%s) has not been recognized.'
                                     'States that are supported to check: online, offline', state)
        return self.get_s1_link_status(session, timeout=timeout) == state

